const shareLockGroups = `-- name: ShareLockGroups :many
SELECT id, org_id, display_name, machine_name, keycloak_group_id, deleted_at, sync_status, sync_attempts, next_sync_at, last_error, created_at, updated_at FROM groups
WHERE org_id = $1 AND id = ANY($2::text[]) AND deleted_at IS NULL
ORDER BY id
FOR SHARE
`

type ShareLockGroupsParams struct {
	OrgID string
	Ids   []string
}

// The live groups of the organization among ids, held FOR SHARE while they
// are bound so none is deleted half-way (deleting takes them FOR UPDATE).
func (q *Queries) ShareLockGroups(ctx context.Context, arg ShareLockGroupsParams) ([]Group, error) {
	rows, err := q.db.Query(ctx, shareLockGroups, arg.OrgID, arg.Ids)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []Group
	for rows.Next() {
		var i Group
		if err := rows.Scan(
			&i.ID,
			&i.OrgID,
			&i.DisplayName,
			&i.MachineName,
			&i.KeycloakGroupID,
			&i.DeletedAt,
			&i.SyncStatus,
			&i.SyncAttempts,
			&i.NextSyncAt,
			&i.LastError,
			&i.CreatedAt,
			&i.UpdatedAt,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

