const upsertWorkspaceBinding = `-- name: UpsertWorkspaceBinding :exec
INSERT INTO workspace_group_bindings (workspace_id, group_id, org_id, role) VALUES ($1, $2, $3, $4)
ON CONFLICT (workspace_id, group_id) DO UPDATE SET role = EXCLUDED.role, updated_at = now()
`

type UpsertWorkspaceBindingParams struct {
	WorkspaceID string
	GroupID     string
	OrgID       string
	Role        string
}

func (q *Queries) UpsertWorkspaceBinding(ctx context.Context, arg UpsertWorkspaceBindingParams) error {
	_, err := q.db.Exec(ctx, upsertWorkspaceBinding,
		arg.WorkspaceID,
		arg.GroupID,
		arg.OrgID,
		arg.Role,
	)
	return err
}

const userHasWorkspaceBinding = `-- name: UserHasWorkspaceBinding :one
SELECT EXISTS (
    SELECT 1 FROM workspace_group_bindings b
    JOIN groups g ON g.id = b.group_id AND g.deleted_at IS NULL
    JOIN group_members gm ON gm.group_id = b.group_id AND gm.deleted_at IS NULL
    JOIN workspaces w ON w.id = b.workspace_id AND w.state <> 'Deleted'
    WHERE gm.user_id = $1
)
`

// Whether the user belongs in tenantry:tenant-users: a member of a live
// group bound to a Workspace not Deleted (PRODUCT-PLAN §9.3).
func (q *Queries) UserHasWorkspaceBinding(ctx context.Context, userID string) (bool, error) {
	row := q.db.QueryRow(ctx, userHasWorkspaceBinding, userID)
	var exists bool
	err := row.Scan(&exists)
	return exists, err
}

const workspaceNodeOvercommitted = `-- name: WorkspaceNodeOvercommitted :one
SELECT EXISTS (
    SELECT 1 FROM workspace_node_reservations r JOIN dedicated_node_grants g ON g.id = r.node_grant_id
    WHERE r.workspace_id = $1 AND g.capacity_state = 'Overcommitted'
)
`

// Whether a Dedicated Workspace's node holds more than it can (drift: a
// larger system reserve, a smaller node; 04-state-machines §5.3).
func (q *Queries) WorkspaceNodeOvercommitted(ctx context.Context, workspaceID string) (bool, error) {
	row := q.db.QueryRow(ctx, workspaceNodeOvercommitted, workspaceID)
	var exists bool
	err := row.Scan(&exists)
	return exists, err
}

